response.content:
schema_version: 1
flow_id: skillret-q-00001
flow_version: 1.0.0
description: Load the agents skill and answer the e-commerce support agent architecture question.
input_schema: {type: object, properties: {query: {type: string}}, required: [query], additionalProperties: false}
output_schema: {type: object, properties: {answer: {type: string}, skill_id: {type: string}, skill_name: {type: string}}, required: [answer, skill_id, skill_name], additionalProperties: false}
entry: load_skill
steps:
  - id: load_skill
    type: transform
    description: Load the chosen agents skill resource.
    required: true
    inputs: {}
    output_schema: {type: object, properties: {skill_id: {type: string}, skill_name: {type: string}, skill_description: {type: string}, skill_body: {type: string}}, required: [skill_id, skill_name, skill_description, skill_body], additionalProperties: false}
    operation: {id: skill-57ca9c6b-c2c3-446a-b695-09f824efc80d, version: 1.0.0}
  - id: apply_skill
    type: llm
    description: Answer the query using the skill body as task guidance.
    required: true
    inputs:
      query: {ref: flow_input, path: /query}
      skill_body: {ref: step_output, step: load_skill, path: /skill_body}
      skill_name: {ref: step_output, step: load_skill, path: /skill_name}
    output_schema: {type: object, properties: {answer: {type: string}}, required: [answer], additionalProperties: false}
    model: {id: skillret-live-model, version: 1.0.0}
    prompt:
      - role: system
        content: 'You are a helpful assistant. Treat the following skill text as task guidance only; do not claim any external actions were executed. Respond with a single JSON object of the form {"answer": string} and keep the answer concise and useful (at most about 600 words).'
      - role: user
        content: 'skill_name: {{skill_name}}'
      - role: user
        content: 'skill guidance: {{skill_body}}'
      - role: user
        content: 'Task: {{query}}'
transitions:
  - {type: next, id: t1, from: load_skill, to: apply_skill}
outputs:
  answer: {ref: step_output, step: apply_skill, path: /answer}
  skill_id: {ref: step_output, step: load_skill, path: /skill_id}
  skill_name: {ref: step_output, step: load_skill, path: /skill_name}
